import type { Express } from "express";
import { createServer, type Server } from "http";
import { static as expressStatic } from "express";
import { storage } from "./storage";
import multer from "multer";
import path from "path";
import { insertProjectSchema, insertContactSchema, insertFileSchema } from "@shared/schema";
import { z } from "zod";
import fs from "fs";

// Configure multer for file uploads
const uploadsDir = path.join(process.cwd(), "uploads");
if (!fs.existsSync(uploadsDir)) {
  fs.mkdirSync(uploadsDir, { recursive: true });
}

const storage_multer = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadsDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, file.fieldname + '-' + uniqueSuffix + path.extname(file.originalname));
  }
});

const upload = multer({ 
  storage: storage_multer,
  limits: {
    fileSize: 10 * 1024 * 1024, // 10MB limit
  },
  fileFilter: (req, file, cb) => {
    const allowedTypes = /jpeg|jpg|png|gif|pdf|doc|docx|ppt|pptx|dwg|txt|xls|xlsx|csv|zip|rar/;
    const allowedMimeTypes = [
      'image/jpeg', 'image/jpg', 'image/png', 'image/gif',
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-powerpoint',
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      'text/plain',
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'text/csv',
      'application/zip',
      'application/x-rar-compressed'
    ];

    const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());
    const mimetype = allowedMimeTypes.includes(file.mimetype) || allowedTypes.test(file.mimetype);

    console.log('File validation:', { 
      filename: file.originalname, 
      mimetype: file.mimetype, 
      extname, 
      mimetypeValid: mimetype 
    });

    if (mimetype && extname) {
      return cb(null, true);
    } else {
      cb(new Error(`Invalid file type: ${file.mimetype}. Allowed types: PDF, DOC, DOCX, PPT, PPTX, images, TXT, XLS, XLSX, CSV, ZIP`));
    }
  }
});

export async function registerRoutes(app: Express): Promise<Server> {

  // Static file serving for attached assets
  const attachedAssetsPath = path.join(process.cwd(), 'attached_assets');
  app.use('/attached_assets', expressStatic(attachedAssetsPath));

  // Projects API
  app.get("/api/projects", async (req, res) => {
    try {
      const projects = await storage.getProjects();
      res.json(projects);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch projects" });
    }
  });

  app.get("/api/projects/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const project = await storage.getProject(id);
      if (!project) {
        return res.status(404).json({ message: "Project not found" });
      }
      res.json(project);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch project" });
    }
  });

  app.post("/api/projects", upload.single('file'), async (req, res) => {
    try {
      let projectData = req.body;

      // Parse tools array if it's a string
      if (typeof projectData.tools === 'string') {
        try {
          projectData.tools = JSON.parse(projectData.tools);
        } catch {
          projectData.tools = projectData.tools.split(',').map((tool: string) => tool.trim());
        }
      }

      // Handle file upload
      if (req.file) {
        const fileRecord = await storage.createFile({
          filename: req.file.filename,
          originalName: req.file.originalname,
          mimetype: req.file.mimetype,
          size: req.file.size,
          path: req.file.path
        });
        projectData.fileUrl = `/api/files/${fileRecord.id}`;
      }

      const validatedData = insertProjectSchema.parse(projectData);
      const project = await storage.createProject(validatedData);
      res.status(201).json(project);
    } catch (error) {
      if (error instanceof z.ZodError) {
        res.status(400).json({ message: "Invalid project data", errors: error.errors });
      } else {
        res.status(500).json({ message: "Failed to create project" });
      }
    }
  });



  // Skills API
  app.get("/api/skills", async (req, res) => {
    try {
      const skills = await storage.getSkills();
      res.json(skills);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch skills" });
    }
  });

  // Experiences API
  app.get("/api/experiences", async (req, res) => {
    try {
      const type = req.query.type as string;
      const experiences = type 
        ? await storage.getExperiencesByType(type)
        : await storage.getExperiences();
      res.json(experiences);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch experiences" });
    }
  });

  // Contact API
  app.post("/api/contact", async (req, res) => {
    try {
      const validatedData = insertContactSchema.parse(req.body);
      const contact = await storage.createContact(validatedData);
      res.status(201).json({ message: "Message sent successfully" });
    } catch (error) {
      if (error instanceof z.ZodError) {
        res.status(400).json({ message: "Invalid contact data", errors: error.errors });
      } else {
        res.status(500).json({ message: "Failed to send message" });
      }
    }
  });

  // Admin endpoint to view contact messages
  app.get("/api/admin/contacts", async (req, res) => {
    try {
      const contacts = await storage.getContacts();
      res.json(contacts);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch contacts" });
    }
  });

  // File upload API
  app.post("/api/upload", (req, res) => {
    upload.single('file')(req, res, async (err) => {
      try {
        if (err) {
          console.error('Multer error:', err);
          return res.status(400).json({ message: `Upload error: ${err.message}` });
        }

        if (!req.file) {
          console.error('No file in request:', req.body);
          return res.status(400).json({ message: "No file uploaded" });
        }

        console.log('File received:', req.file);

        const fileRecord = await storage.createFile({
          filename: req.file.filename,
          originalName: req.file.originalname,
          mimetype: req.file.mimetype,
          size: req.file.size,
          path: req.file.path
        });

        console.log('File record created:', fileRecord);

        res.status(201).json({ 
          id: fileRecord.id,
          url: `/api/files/${fileRecord.id}`,
          originalName: fileRecord.originalName
        });
      } catch (error) {
        console.error('Upload processing error:', error);
        res.status(500).json({ message: "Failed to upload file" });
      }
    });
  });

  // File serving API
  app.get("/api/files/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const file = await storage.getFile(id);

      if (!file) {
        return res.status(404).json({ message: "File not found" });
      }

      if (!fs.existsSync(file.path)) {
        return res.status(404).json({ message: "File not found on disk" });
      }

      res.setHeader('Content-Type', file.mimetype);
      res.setHeader('Content-Disposition', `inline; filename="${file.originalName}"`);
      res.sendFile(path.resolve(file.path));
    } catch (error) {
      res.status(500).json({ message: "Failed to serve file" });
    }
  });

  // Profile image upload
  app.post("/api/profile-image", upload.single('image'), async (req, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ message: "No image uploaded" });
      }

      const fileRecord = await storage.createFile({
        filename: req.file.filename,
        originalName: req.file.originalname,
        mimetype: req.file.mimetype,
        size: req.file.size,
        path: req.file.path
      });

      res.status(201).json({ 
        id: fileRecord.id,
        url: `/api/files/${fileRecord.id}`,
        originalName: fileRecord.originalName
      });
    } catch (error) {
      res.status(500).json({ message: "Failed to upload profile image" });
    }
  });

  const httpServer = createServer(app);
  return httpServer;
}

