import { 
  users, projects, blogPosts, skills, experiences, contacts, files,
  type User, type InsertUser, type Project, type InsertProject,
  type BlogPost, type InsertBlogPost, type Skill, type InsertSkill,
  type Experience, type InsertExperience, type Contact, type InsertContact,
  type FileRecord, type InsertFile
} from "@shared/schema";

export interface IStorage {
  // User operations
  getUser(id: number): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;

  // Project operations
  getProjects(): Promise<Project[]>;
  getProject(id: number): Promise<Project | undefined>;
  createProject(project: InsertProject): Promise<Project>;
  updateProject(id: number, project: Partial<InsertProject>): Promise<Project | undefined>;
  deleteProject(id: number): Promise<boolean>;

  // Blog operations
  getBlogPosts(): Promise<BlogPost[]>;
  getPublishedBlogPosts(): Promise<BlogPost[]>;
  getBlogPost(id: number): Promise<BlogPost | undefined>;
  createBlogPost(post: InsertBlogPost): Promise<BlogPost>;
  updateBlogPost(id: number, post: Partial<InsertBlogPost>): Promise<BlogPost | undefined>;
  deleteBlogPost(id: number): Promise<boolean>;

  // Skill operations
  getSkills(): Promise<Skill[]>;
  createSkill(skill: InsertSkill): Promise<Skill>;

  // Experience operations
  getExperiences(): Promise<Experience[]>;
  getExperiencesByType(type: string): Promise<Experience[]>;
  createExperience(experience: InsertExperience): Promise<Experience>;

  // Contact operations
  createContact(contact: InsertContact): Promise<Contact>;
  getContacts(): Promise<Contact[]>;

  // File operations
  createFile(file: InsertFile): Promise<FileRecord>;
  getFile(id: number): Promise<FileRecord | undefined>;
}

export class MemStorage implements IStorage {
  private users: Map<number, User>;
  private projects: Map<number, Project>;
  private blogPosts: Map<number, BlogPost>;
  private skills: Map<number, Skill>;
  private experiences: Map<number, Experience>;
  private contacts: Map<number, Contact>;
  private files: Map<number, FileRecord>;

  private currentUserId: number;
  private currentProjectId: number;
  private currentBlogPostId: number;
  private currentSkillId: number;
  private currentExperienceId: number;
  private currentContactId: number;
  private currentFileId: number;

  constructor() {
    this.users = new Map();
    this.projects = new Map();
    this.blogPosts = new Map();
    this.skills = new Map();
    this.experiences = new Map();
    this.contacts = new Map();
    this.files = new Map();

    this.currentUserId = 1;
    this.currentProjectId = 1;
    this.currentBlogPostId = 1;
    this.currentSkillId = 1;
