interface BlogPost {
  id: number;
  title: string;
  content: string;
  excerpt?: string;
  isPublished: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export function CurrentWorkSection() {
  const [newPostTitle, setNewPostTitle] = useState("");
  const [newPostContent, setNewPostContent] = useState("");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: blogPosts, isLoading } = useQuery<BlogPost[]>({
    queryKey: ["/api/blog-posts"],
  });

  const createPostMutation = useMutation({
    mutationFn: async (data: { title: string; content: string; excerpt: string; isPublished: boolean }) => {
      const response = await apiRequest('POST', '/api/blog-posts', data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/blog-posts"] });
      setNewPostTitle("");
      setNewPostContent("");
      setIsDialogOpen(false);
      toast({
        title: "Success",
        description: "Blog post created successfully!",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to create blog post. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleCreatePost = () => {
    if (!newPostTitle.trim() || !newPostContent.trim()) {
      toast({
        title: "Validation Error",
        description: "Please fill in both title and content.",
        variant: "destructive",
      });
      return;
    }

    const excerpt = newPostContent.slice(0, 150) + (newPostContent.length > 150 ? "..." : "");

    createPostMutation.mutate({
      title: newPostTitle,
      content: newPostContent,
      excerpt,
      isPublished: true,
    });
  };

  const learningProgress = [
    { skill: "JavaScript", progress: 75, color: "bg-primary" },
    { skill: "React", progress: 60, color: "bg-green-500" },
    { skill: "Node.js", progress: 45, color: "bg-purple-600" },
