  const quickStats = [
    { label: "GitHub Commits", value: "247" },
    { label: "Days Coding", value: "89" },
    { label: "Projects Completed", value: "12" },
  ];

  return (
    <section id="current-work" className="py-20 bg-white dark:bg-gray-900">
